    norm_a_inertial = adcs_vec3_norm(inertial_a);
    norm_b_inertial = adcs_vec3_norm(inertial_b);
    norm_a_body = adcs_vec3_norm(body_a);
    norm_b_body = adcs_vec3_norm(body_b);

    if ((!isfinite(norm_a_inertial)) || (!isfinite(norm_b_inertial)) || 
        (!isfinite(norm_a_body)) || (!isfinite(norm_b_body)) ||
        (norm_a_inertial <= ADCS_EPS_NORM) || (norm_b_inertial <= ADCS_EPS_NORM) ||
        (norm_a_body <= ADCS_EPS_NORM) || (norm_b_body <= ADCS_EPS_NORM)) {
        *mismatch_rad = INFINITY;
        return ADCS_E_DEGENERATE;
    }

    // Normalize inertial vectors
    if (adcs_vec3_normalize(inertial_a, ADCS_EPS_NORM, &unit_a_inertial) != ADCS_OK) {
        *mismatch_rad = INFINITY;
        return ADCS_E_DEGENERATE;
    }
    if (adcs_vec3_normalize(inertial_b, ADCS_EPS_NORM, &unit_b_inertial) != ADCS_OK) {
        *mismatch_rad = INFINITY;
        return ADCS_E_DEGENERATE;
    }

    // Compute inertial angle
    dot_inertial = adcs_vec3_dot(&unit_a_inertial, &unit_b_inertial);
    dot_inertial = ADCS_CLAMP(dot_inertial, -1.0, 1.0);
    angle_inertial = acos(dot_inertial);

    // Normalize body vectors
    if (adcs_vec3_normalize(body_a, ADCS_EPS_NORM, &unit_a_body) != ADCS_OK) {
        *mismatch_rad = INFINITY;
        return ADCS_E_DEGENERATE;
    }
    if (adcs_vec3_normalize(body_b, ADCS_EPS_NORM, &unit_b_body) != ADCS_OK) {
        *mismatch_rad = INFINITY;
        return ADCS_E_DEGENERATE;
