    dot_body = adcs_vec3_dot(&unit_a_body, &unit_b_body);
    dot_body = ADCS_CLAMP(dot_body, -1.0, 1.0);
    angle_body = acos(dot_body);

    // Compute mismatch
    mismatch = fabs(angle_inertial - angle_body);

    *mismatch_rad = mismatch;
    return ADCS_OK;
}

